#!/usr/bin/env python3
"""Regenerates Core/include/vv/presetgen_recipes.hpp and presetgen_init.hpp from the web-side sources (gen/recipes.json, gen/init_preset.json)."""
import json, os, sys
root = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..'); gen = sys.argv[1] if len(sys.argv) > 1 else '/home/claude/gen'
r = json.load(open(os.path.join(gen, 'recipes.json'))); init = open(os.path.join(gen, 'init_preset.json')).read()
inc = os.path.join(root, 'Core/include/vv')
open(os.path.join(inc, 'presetgen_recipes.hpp'), 'w').write('// GENERATED by tools/export_gen_recipes.py from gen/recipes.json. Do not edit.\n#pragma once\nnamespace vv { namespace presetgen {\ninline const char* kGenRecipes = R"VVJSON(' + json.dumps(r, separators=(',', ':')) + ')VVJSON";\n} }\n')
open(os.path.join(inc, 'presetgen_init.hpp'), 'w').write('// GENERATED by tools/export_gen_recipes.py from the web INIT preset. Do not edit.\n#pragma once\nnamespace vv { namespace presetgen {\ninline const char* kInitPreset = R"VVJSON(' + init + ')VVJSON";\n} }\n')
